const estadoHttp = (x) => (x.statusCode ? 'HTTP ' + x.statusCode
  : 'sin respuesta' + (x.error && x.error.message ? ': ' + x.error.message : ''));
let reason = '';
if ($('Guardar borrador').isExecuted) {
  const g = $('Guardar borrador').first().json || {};
  const b = cuerpo(g);
